from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product, combinations


def _dependency_solver(data, ascending, maximize):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    choices = []
    for name in names:
        versions = [v for v in rows[name]
                    if v not in blocked.get(name, [])
                    and (name not in pins or v == pins[name])]
        choices.append([None] + versions)

    best_vector = None
    best = None
    for values in product(*choices):
        selected = dict(zip(names, values))
        if any(selected.get(name) is None or
               not bounds[0] <= selected[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        edges = {name: [] for name in names if selected[name] is not None}
        valid = True
        for name, version in selected.items():
            if version is None:
                continue
            for dep in rows[name][version].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                value = selected[target]
                if value is None or not dep["min"] <= value <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue
        # The installed packages must be precisely the closure of the roots.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges[name])
        if any(selected[name] is not None for name in names if name not in reachable):
            continue
        state, finished = set(), set()
        def visit(name):
            if name in state:
                return False
            if name in finished:
                return True
            state.add(name)
            if any(not visit(other) for other in edges[name]):
                return False
            state.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in edges):
            continue
        vector = tuple(-1 if selected[n] is None else selected[n]
                       for n in (names if ascending else reversed(names)))
        if best_vector is None or (vector > best_vector if maximize else vector < best_vector):
            best_vector = vector
            best = {n: v for n, v in selected.items() if v is not None}
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _build_dependency(ascending, maximize):
    return lambda data: _dependency_solver(data, ascending, maximize)


def _round(n, denominator, mode):
    if mode == "half_up":
        return (2 * n + denominator) // (2 * denominator)
    return n // denominator


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)
    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, mode)
        tax = _round(raw * event.get("tax_bp", 0), 10000, mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _jobs(data):
    jobs = [j for j in data["jobs"] if j["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = [j["id"] for j in subset]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active = []
        valid = True
        for job in sorted(subset, key=lambda j: (j["start"], j["end"], j["id"])):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(j["value"] for j in subset)
        ordered_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and ordered_ids > best_ids)):
            best_value, best_ids = value, ordered_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _routes(data):
    import heapq
    required = data.get("required", [])
    indexes = {node: i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    mask0 = 1 << indexes[data["source"]] if data["source"] in indexes else 0
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    start_state = (data["source"], mask0, data["coupons"])
    dist = {start_state: data["start"]}
    queue = [(data["start"],) + start_state]
    while queue:
        time, node, mask, left = heapq.heappop(queue)
        state = (node, mask, left)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], left)]
            if left:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), left - 1))
            for duration, remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | (1 << indexes[nxt] if nxt in indexes else 0)
                next_state = (nxt, next_mask, remaining)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival,) + next_state)
    return {"arrival": None}


SOLVERS = {
    "component_01": _build_dependency(False, True),
    "component_02": _build_dependency(False, False),
    "component_03": _build_dependency(True, True),
    "component_04": _build_dependency(True, False),
    "component_05": _build_dependency(False, True),
    "component_06": _ledger,
    "component_07": _jobs,
    "component_08": _routes,
}
